 let checkOwner:number|null=initialBall;const sequenceWarnings:string[]=[];
 for(const m of orderedMoves){if(m.rival||!['Pass','Shoot','Carry','Dribble','Shield'].includes(m.kind))continue;if(checkOwner!==m.player){sequenceWarnings.push('Step '+(m.stage??1)+': #'+(m.player+1)+' has no ball');continue}if(m.kind==='Carry'||m.kind==='Dribble'||m.kind==='Shield')continue;if(m.kind==='Shoot')checkOwner=null;else if(m.receiver!==undefined&&m.receiver!==m.player&&players[m.receiver])checkOwner=m.receiver;else{sequenceWarnings.push('Step '+(m.stage??1)+': free target — reception not verified');checkOwner=null;}}

