 const [freePass,setFreePass]=useState(false);
 const passTo=(to:number)=>{const from=currentOwner;if(from===null){setPassNotice('Top boşta. Önceki pası veya şutu düzenleyin.');return;}if(to===from||!visiblePlayers[to]||movements.length>=1000){setPassNotice('Farklı bir hedef oyuncu seçin.');return;}const target=[...orderedMoves].reverse().find(m=>!m.rival&&m.player===to&&(m.stage??1)<=stage&&m.kind!=='Pass'&&m.kind!=='Shoot')??visiblePlayers[to];onMovements([...movements,{player:from,kind:'Pass',x:target.x,y:target.y,receiver:to,stage}]);setReceiver(-1);setSelected(to);setPassNotice('#'+(from+1)+' → #'+(to+1)+' pas eklendi')};
