 const makeScenario=():Movement[]=>{const clamp=(v:number,min:number,max:number)=>Math.max(min,Math.min(max,v));const field=players.map((p,i)=>({p,i})).filter(v=>v.i!==0);const front=[...field].sort((a,b)=>b.p.x-a.p.x),back=[...field].sort((a,b)=>a.p.x-b.p.x);const wide=[...field].sort((a,b)=>Math.abs(b.p.y-40)-Math.abs(a.p.y-40));const move=(v:typeof field[number],dx:number,dy:number,kind:Movement['kind']='Run',delay=0):Movement=>({player:v.i,kind,x:clamp(v.p.x+dx,4,116),y:clamp(v.p.y+dy,4,76),duration:2,delay});const pass=(a:typeof field[number],b:typeof field[number],delay=0):Movement=>({player:a.i,kind:'Pass',receiver:b.i,x:b.p.x,y:b.p.y,duration:1,delay});if(field.length<3)return [];switch(scenario){case 'high':return front.slice(0,4).map(v=>move(v,16,(40-v.p.y)*.25,'Press'));case 'low':return field.map(v=>move(v,-18,(40-v.p.y)*.35));case 'counter':return [pass(back[0],front[0]),...front.slice(0,3).map(v=>move(v,20,0,'Run',1))];case 'build':return [pass(back[0],back[1]),pass(back[1],front[0],1),...wide.slice(0,2).map(v=>move(v,5,v.p.y<40?-6:6))];case 'overlap':return wide.slice(0,2).flatMap(v=>[move(v,12,v.p.y<40?-5:5),{...move(v,25,0),delay:.5}]);case 'gegen':return front.slice(0,5).map(v=>move(v,6,(40-v.p.y)*.45,'Press'));case 'deftrans':return field.map(v=>move(v,-15,(40-v.p.y)*.2));default:return field.map(v=>move(v,12,0))}};
 const applyScenario=(next:Movement[])=>{if(movements.length&&!window.confirm('Mevcut hareketler bu senaryoyla değiştirilsin mi?'))return;onMovements(next.map(m=>({...m})));setScenarioStatus('Senaryo yüklendi. Hareketleri düzenleyebilirsiniz.')};
