 const startDraw=(e:React.PointerEvent<SVGSVGElement>)=>{if(drawTool==='off'||e.button!==0)return;e.preventDefault();setPlaying(false);const p=drawPoint(e);drawing.current={kind:drawTool,color:drawColor,points:[p,p]};setDraftDraw(drawing.current);e.currentTarget.setPointerCapture(e.pointerId)};
 const moveDraw=(e:React.PointerEvent<SVGSVGElement>)=>{const d=drawing.current;if(!d)return;const p=drawPoint(e);drawing.current={...d,points:d.kind==='pen'?[...d.points.slice(0,1999),p]:[d.points[0],p]};setDraftDraw(drawing.current)};
 const finishDraw=(e:React.PointerEvent<SVGSVGElement>)=>{if(!drawing.current)return;moveDraw(e);const d=drawing.current;drawing.current=null;setDraftDraw(null);if(d){setAnnotations(old=>[...old,d].slice(-200));setRedoDraw([])}};
 const undoDraw=()=>{if(!annotations.length)return;setRedoDraw(old=>[...old,annotations[annotations.length-1]]);setAnnotations(old=>old.slice(0,-1))};
 const redoAnnotation=()=>{if(!redoDraw.length)return;setAnnotations(old=>[...old,redoDraw[redoDraw.length-1]]);setRedoDraw(old=>old.slice(0,-1))};
 const annotationLayer=<svg viewBox="0 0 120 80" aria-label="Presentation drawing layer" style={{position:'absolute',inset:0,width:'100%',height:'100%',touchAction:drawTool==='off'?'auto':'none',pointerEvents:drawTool==='off'?'none':'auto',cursor:drawTool==='off'?'default':'crosshair'}} onPointerDown={startDraw} onPointerMove={moveDraw} onPointerUp={finishDraw} onPointerCancel={()=>{drawing.current=null;setDraftDraw(null)}}>{[...annotations,...(draftDraw?[draftDraw]:[])].map((a,i)=>{const p=a.points[0],q=a.points[a.points.length-1],dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy),angle=Math.atan2(dy,dx);return <g key={i} stroke={a.color} strokeWidth=".8" fill="none" strokeLinecap="round" strokeLinejoin="round">{a.kind==='pen'?<polyline points={a.points.map(v=>v.x+','+v.y).join(' ')}/>:a.kind==='circle'?<ellipse cx={(p.x+q.x)/2} cy={(p.y+q.y)/2} rx={Math.abs(dx)/2} ry={Math.abs(dy)/2}/>:a.kind==='rect'||a.kind==='zone'?<rect x={Math.min(p.x,q.x)} y={Math.min(p.y,q.y)} width={Math.abs(dx)} height={Math.abs(dy)} fill={a.kind==='zone'?a.color:'none'} fillOpacity=".2"/>:<><line x1={p.x} y1={p.y} x2={q.x} y2={q.y}/>{a.kind==='arrow'&&len>1&&<path d={'M'+(q.x-3*Math.cos(angle-.5))+' '+(q.y-3*Math.sin(angle-.5))+' L'+q.x+' '+q.y+' L'+(q.x-3*Math.cos(angle+.5))+' '+(q.y-3*Math.sin(angle+.5))}/>}{a.kind==='measure'&&<text x={(p.x+q.x)/2} y={(p.y+q.y)/2-2} fill={a.color} stroke="none" fontSize="3" textAnchor="middle">{len.toFixed(1)} units</text>}</>}</g>})}</svg>;

 const stepPresentation=(direction:number)=>{setPlaying(false);setTime(direction<0?[...boundaries].reverse().find(v=>v<t-.0001)??0:boundaries.find(v=>v>t+.0001)??duration)};
 const togglePresentationPlay=()=>{if(!duration)return;if(playing)setPlaying(false);else{if(t>=duration)setTime(0);setPlaying(true)}};
 const closePresentation=()=>{if(recording)stopVideo();setPlaying(false);setPresenting(false);if(document.fullscreenElement===presentationRef.current)void document.exitFullscreen().catch(()=>{})};
 useEffect(()=>{if(!presenting)return;presentationRef.current?.focus();const onKey=(e:KeyboardEvent)=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement||e.target instanceof HTMLButtonElement&&e.code==='Space')return;if(e.key==='Escape'){closePresentation();return}if(e.code==='Space'){e.preventDefault();togglePresentationPlay()}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();stepPresentation(e.key==='ArrowLeft'?-1:1)}else if(e.key==='Home'){e.preventDefault();setPlaying(false);setTime(0)}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[presenting,t,playing,duration,boundaries]);
 const pitch=<svg viewBox="0 0 120 80" style={{width:'100%',maxWidth:presenting?'min(100%, 105vh)':850,background:'#153c30',borderRadius:8}} role="img" aria-label="Taktik hareket önizlemesi"><g fill="none" stroke="#b9d6ca" strokeWidth=".4"><rect x="1" y="1" width="118" height="78"/><path d="M60 1V79"/><circle cx="60" cy="40" r="9"/><rect x="1" y="18" width="17" height="44"/><rect x="102" y="18" width="17" height="44"/></g>{heatData.map(c=><rect key={'heat-'+c.x+'-'+c.y} x={c.x-5} y={c.y-5} width="10" height="10" fill={heatMode==='control'?(c.value>=0?'#60a5fa':'#fb7185'):Math.abs(c.value)/heatMax>.65?'#ef4444':Math.abs(c.value)/heatMax>.3?'#facc15':'#22c55e'} opacity={Math.abs(c.value)/heatMax*.65}/>)}{Array.from(network.entries()).map(([key,count])=>{const [a,b]=key.split(':').map(Number);return <line key={'net-'+key} x1={positions[a].x} y1={positions[a].y} x2={positions[b].x} y2={positions[b].y} stroke="#facc15" strokeWidth={Math.min(3,.5+count*.4)} opacity=".8"/>})}{showAnalysis&&carrier&&bestPass&&<line x1={carrier.x} y1={carrier.y} x2={bestPass.p.x} y2={bestPass.p.y} stroke="#facc15" strokeWidth="1.4" opacity=".9"/>}{showAnalysis&&bestRun&&<g><line x1={bestRun.q.x} y1={bestRun.q.y} x2={bestRun.p.x} y2={bestRun.p.y} stroke="#c084fc" strokeWidth="1" strokeDasharray="2 1"/><circle cx={bestRun.p.x} cy={bestRun.p.y} r="2.5" fill="none" stroke="#c084fc" strokeWidth=".8"/></g>}{showAnalysis&&spaces.map((p,i)=><circle key={'space-'+i} cx={p.x} cy={p.y} r="4" fill="#bef264" fillOpacity=".18" stroke="#bef264" strokeWidth=".4" strokeDasharray="1 1"/>)}{showAnalysis&&carrier&&lanes.map(l=><line key={'lane-'+l.i} x1={carrier.x} y1={carrier.y} x2={l.p.x} y2={l.p.y} stroke={l.clearance>=3?'#bef264':'#fb7185'} strokeWidth=".6" strokeDasharray="2 1" opacity=".8"/>)}{rivalPositions.map((p,i)=><g key={'def-'+i}><circle cx={p.x} cy={p.y} r="3.1" fill="#fb7185" stroke={interceptor===i?'white':'#351018'} strokeWidth={interceptor===i?'.8':'.3'}/><text x={p.x} y={p.y+1} textAnchor="middle" fontSize="2.5" fill="#351018">R{i+1}</text></g>)}{positions.map((p,i)=><g key={i}><circle cx={p.x} cy={p.y} r="3.4" fill={(presenting?presentPlayer===i:highlight===i)?"#fbbf24":"#bef264"}/><text x={p.x} y={p.y+1} textAnchor="middle" fontSize="2.8" fill="#10251c">{i+1}</text></g>)}<circle cx={ball.x} cy={ball.y} r="1.5" fill="white" stroke="#111" strokeWidth=".4"/></svg>;
 const activeSteps=timelines.flat().filter(v=>v.start<=t&&t<v.end);
 return <section style={{marginTop:24}}><h3>Tactical Animation</h3><button type="button" onClick={()=>{setPlaying(false);setPresenting(true)}}>Presentation Mode</button>{presenting&&<div ref={presentationRef} tabIndex={-1} role="dialog" aria-modal="true" aria-label="Tactical presentation" style={{position:'fixed',inset:0,zIndex:9999,background:'#101719',color:'#f1f5f9',overflow:'auto',padding:16,display:'flex',flexDirection:'column',alignItems:'center',gap:10}}><div style={{display:'flex',gap:12,alignItems:'center',width:'100%',flexWrap:'wrap'}}><h2 style={{margin:0,flex:1}}>TACTIQRA · Tactical Presentation</h2><button type="button" onClick={()=>{if(document.fullscreenElement===presentationRef.current)void document.exitFullscreen().catch(()=>{});else void presentationRef.current?.requestFullscreen?.().catch(()=>{})}}>Fullscreen</button><button type="button" onClick={closePresentation}>Exit</button></div><div role="group" aria-label="Drawing tools" style={{display:'flex',gap:6,flexWrap:'wrap',justifyContent:'center'}}>{[['off','Pointer'],['pen','Pen'],['arrow','Arrow'],['circle','Circle'],['rect','Rectangle'],['zone','Zone'],['measure','Measure']].map(([id,label])=><button key={id} type="button" aria-pressed={drawTool===id} style={{color:drawTool===id?'#bef264':undefined}} onClick={()=>setDrawTool(id)}>{label}</button>)}<label>Color <input type="color" value={drawColor} onChange={e=>setDrawColor(e.target.value)}/></label><button type="button" disabled={!annotations.length} onClick={undoDraw}>Undo</button><button type="button" disabled={!redoDraw.length} onClick={redoAnnotation}>Redo</button><button type="button" disabled={!annotations.length} onClick={()=>{if(window.confirm('Clear presentation drawings?')){setAnnotations([]);setRedoDraw([])}}}>Clear Drawings</button></div><div style={{display:'flex',gap:8,flexWrap:'wrap',alignItems:'center'}}><label>Video resolution <select disabled={recording} value={videoSize} onChange={e=>setVideoSize(Number(e.target.value))}><option value={720}>720 × 480</option><option value={1080}>1080 × 720</option><option value={1920}>1920 × 1280</option></select></label><button type="button" disabled={!duration||recording} onClick={startVideo}>Record video</button><button type="button" disabled={!recording} onClick={stopVideo}>Stop &amp; download</button><span role="status">{videoStatus}</span></div><div ref={videoPitchRef} style={{position:'relative',width:'min(100%, 105vh)',aspectRatio:'3 / 2',flexShrink:0}}>{pitch}{annotationLayer}</div><div style={{display:'flex',gap:10,flexWrap:'wrap',justifyContent:'center'}}><button type="button" onClick={()=>{setPlaying(false);setTime(0)}}>⏮ Reset</button><button type="button" disabled={t<=0} onClick={()=>stepPresentation(-1)}>← Previous</button><button type="button" disabled={!duration} onClick={togglePresentationPlay}>{playing?'Pause':'Play'}</button><button type="button" disabled={t>=duration} onClick={()=>stepPresentation(1)}>Next →</button><label>Speed <select value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value=".5">0.5×</option><option value="1">1×</option><option value="2">2×</option></select></label></div><label style={{width:'min(850px,100%)'}}>Time {t.toFixed(1)} / {duration.toFixed(1)}s <input style={{width:'100%'}} type="range" min="0" max={duration||1} step=".05" disabled={!duration} value={t} onChange={e=>{setPlaying(false);setTime(Number(e.target.value))}}/></label><label>Highlight player <select value={presentPlayer} onChange={e=>setPresentPlayer(Number(e.target.value))}><option value={-1}>All players</option>{players.map((p,i)=><option key={i} value={i}>#{i+1} {p.name}</option>)}</select></label>{presentPlayer>=0&&players[presentPlayer]&&<p style={{fontSize:20,margin:0}}>#{presentPlayer+1} {players[presentPlayer].name} · {players[presentPlayer].task||'No assigned task'}</p>}<div style={{fontSize:18}}>{activeSteps.length?activeSteps.map((v,i)=><span key={i} style={{marginRight:16}}>{v.m.rival?'R':'#'}{v.m.player+1} · {v.m.kind}</span>):'Ready / No active movement'}</div><small>Space: Play/Pause · ← →: Step · Home: Reset · Esc: Exit</small></div>}<p>Sıralı modda hareketler tek tek; eş zamanlı modda farklı oyuncular birlikte hareket eder, pas ve şutlar çizim sırasına göre topu bekler. Aynı oyuncunun hareketleri kendi sırasını korur. Varsayılan hareket süresi 2 saniyedir; süre ve bekleme düzenlenebilir. Tek top simülasyonu: top sahibi koşarken topu taşır. Oyuncuya pas, alıcının pas bitişindeki konumuna gider. Serbest hedefte 5 saha birimi içinde takım arkadaşı yoksa top boşta kalır.</p>{pitch}<div className="filters"><label>Başlangıç top sahibi <select value={ownerChoice} onChange={e=>{setPlaying(false);setTime(0);setInitialOwner(Number(e.target.value))}}><option value={-1}>Auto (#{initialOwner+1})</option>{players.map((p,i)=><option key={i} value={i}>#{i+1} {p.name}</option>)}</select></label>{rivals.length>0&&<label>Savunma davranışı <select value={defensiveMode} onChange={e=>{setPlaying(false);setTime(0);setDefensiveMode(e.target.value as typeof defensiveMode)}}><option value="manual">Manual</option><option value="mark">Man marking</option><option value="zone">Zonal defense</option><option value="press">Automatic press</option><option value="line">Defensive line</option></select></label>}{rivals.length>0&&defensiveMode!=='manual'&&<div style={{display:'flex',flexWrap:'wrap',gap:16}}>{([{label:'Pres şiddeti',value:pressIntensity,set:setPressIntensity},{label:'Savunma yoğunluğu',value:compactness,set:setCompactness},{label:'Hat yüksekliği',value:lineHeight,set:setLineHeight}]).map(c=><label key={c.label}>{c.label}: {c.value}% <input type="range" min="0" max="100" step="5" value={c.value} onChange={e=>{setPlaying(false);setTime(0);c.set(Number(e.target.value))}}/></label>)}</div>}{rivals.length>0&&<label><input type="checkbox" checked={defenseEnabled} onChange={e=>{setPlaying(false);setTime(0);setDefenseEnabled(e.target.checked)}}/> Rakip müdahalesi</label>}<label>Heatmap <select value={heatMode} onChange={e=>setHeatMode(e.target.value as typeof heatMode)}><option value="off">Off</option><option value="player">Player Heatmap</option><option value="team">Team Heatmap</option><option value="defense">Defensive Coverage</option><option value="press">Pressing Zones</option><option value="control">Space Control</option><option value="network">Passing Network</option></select></label>{heatMode==='player'&&<label>Oyuncu <select value={heatPlayer} onChange={e=>setHeatPlayer(Number(e.target.value))}>{players.map((p,i)=><option key={i} value={i}>#{i+1} {p.name}</option>)}</select></label>}<label><input type="checkbox" checked={showAnalysis} onChange={e=>setShowAnalysis(e.target.checked)}/> Tactical Analysis</label><label><input type="checkbox" checked={duelEnabled} onChange={e=>{setPlaying(false);setTime(0);setDuelEnabled(e.target.checked)}}/> 1v1 Duel</label><span>Çalım: {duelWins} · Top kaybı: {duelLosses}</span><span>Recover: {recoveries} · Counter passes: {counterPasses}</span><span>Gol: {goals}</span>{interceptor!==null&&<span>Rakip top sahibi: R{interceptor+1}</span>}<span role="status">{activePass?'Top hareket halinde':shotResult|| (owner===null?'Top boşta':'Top sahibi: #'+(owner+1))}{skipped>0?' · Geçersiz pas: '+skipped:''}</span><label>Oynatma modu <select value={mode} onChange={e=>{setPlaying(false);setTime(0);setMode(e.target.value as typeof mode)}}><option value="sequential">Sequential / Sıralı</option><option value="simultaneous">Simultaneous / Eş zamanlı</option><option value="staged">Tactical Sequence / Aşamalı</option></select></label>{mode==='staged'&&<><label>Oynatılacak Step <select value={chosenStage?.stage??1} onChange={e=>{setPlaying(false);setStepChoice(Number(e.target.value))}}>{stageRanges.map(v=><option key={v.stage} value={v.stage}>Step {v.stage}</option>)}</select></label><button type="button" disabled={!chosenStage} onClick={()=>{if(chosenStage)playRange(chosenStage.start,chosenStage.end)}}>Play Current Step</button><button type="button" disabled={!duration} onClick={()=>playRange(0,null)}>Play All Steps</button></>}<button type="button" disabled={!duration} onClick={()=>{if(playing)setPlaying(false);else playRange(time>=(playLimit??duration)?0:time,null)}}>{playing?'Duraklat':'Oynat'}</button><button type="button" onClick={()=>{setPlaying(false);setTime(0)}}>Başa dön</button><button type="button" disabled={!duration||t<=0} onClick={()=>{setPlaying(false);setTime([...boundaries].reverse().find(v=>v<t-.0001)??0)}}>Önceki adım</button><button type="button" disabled={!duration||t>=duration} onClick={()=>{setPlaying(false);setTime(boundaries.find(v=>v>t+.0001)??duration)}}>Sonraki adım</button><label>Hız <select value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value=".5">0.5×</option><option value="1">1×</option><option value="2">2×</option></select></label></div>{heatMode!=='off'&&<p>{heatMode==='network'?'Planlanan oyuncuya pas bağlantıları; tamamlanmış pas istatistiği değildir.':heatMode==='control'?'Mavi: kendi takımına daha yakın alan. Kırmızı: rakibe daha yakın alan.':heatMode==='press'?'Top sahibi çevresindeki rakip yakınlığı; gerçek pres olayları değildir.':'Yeşil → sarı → kırmızı: planlanan hareket yoğunluğu.'} {['defense','press','control'].includes(heatMode)&&!rivals.length?'Rakip takımı gösterin.':''} Simülasyon verisi; gerçek maç tracking verisi değildir.</p>}{showAnalysis&&<section style={{border:'1px solid #334155',borderRadius:8,padding:12,marginTop:12,maxWidth:850}}><h4>Tactical Analysis · {t.toFixed(1)}s</h4><p>Geometrik anlık analiz · saha birimi, gerçek metre veya maç verisi değildir.</p><div style={{display:'flex',gap:16,flexWrap:'wrap'}}><span>Takım genişliği: {ownExtent?.width.toFixed(1)??'—'}</span><span>Takım uzunluğu: {ownExtent?.length.toFixed(1)??'—'}</span><span>Rakip genişliği: {rivalExtent?.width.toFixed(1)??'—'}</span><span>Rakip uzunluğu: {rivalExtent?.length.toFixed(1)??'—'}</span><span>Açık pas: {carrier&&rivalPositions.length?lanes.filter(l=>l.clearance>=3).length:'—'}</span><span>Yerel üstünlük: {local?local.own+'v'+local.rival:'—'}</span></div><p>{rivalPositions.length?'Yeşil daire: erişilebilir boş alan adayı. Yeşil çizgi: açık pas koridoru; kırmızı: engelli. Yerel üstünlük top sahibinin 15 birim çevresinde ölçülür.':'Rakip takımı göstererek boş alan ve pas koridoru analizini etkinleştirin.'}</p><h4>Tactical Recommendations</h4><p>Öneriler anlık geometrik kurallara dayanır; başarı olasılığı veya offside kararı değildir.</p>{!carrier||!rivalPositions.length?<p>Öneri için top sahibi ve rakip takım gerekli.</p>:<div style={{display:'grid',gap:8}}>{bestPass?<div style={{borderLeft:'3px solid #facc15',paddingLeft:10}}><strong>Önerilen pas: #{owner!+1} → #{bestPass.i+1} {bestPass.p.name}</strong><p>Geometrik puan: {bestPass.score}/100 · Koridor açıklığı: {bestPass.clearance.toFixed(1)} · İlerleme: {(bestPass.p.x-carrier.x).toFixed(1)} saha birimi.</p></div>:<p>Açık pas bulunamadı. Topu koru veya destek koşusu oluştur.</p>}{riskCount>0&&<p style={{color:'#fb7185'}}>Risk uyarısı: {riskCount} pas koridorunda rakip yakınlığı var.</p>}{bestRun&&<div style={{borderLeft:'3px solid #c084fc',paddingLeft:10}}><strong>Boş alana koşu: #{bestRun.i+1} {bestRun.q.name}</strong><p>Hedef: {bestRun.p.x}, {bestRun.p.y} · {defensiveEdge!==null&&Number.isFinite(defensiveEdge)&&bestRun.p.x>defensiveEdge?'Savunma hattı arkası adayı; ofsayt kontrolü gerekli.':'İleri destek koşusu adayı.'}</p></div>}{local&&<p>{local.own>local.rival?'Yerel sayısal üstünlük: kısa pas kombinasyonu değerlendir.':local.own<local.rival?'Yerel sayısal dezavantaj: yön değiştirme veya geri destek değerlendir.':'Yerel sayısal denge: destek koşusuyla üstünlük oluştur.'}</p>}</div>}</section>}{showAnalysis&&<section style={{border:'1px solid #334155',borderRadius:8,padding:12,marginTop:12,maxWidth:850}}><h4>Tactical Comparison · A/B</h4><p>Animasyonu durdurup aynı zaman noktasında iki farklı taktik ayarını kaydedin. Karşılaştırma anlık görüntülere dayanır.</p><div style={{display:'flex',gap:8,flexWrap:'wrap'}}><button disabled={!carrier||!rivalPositions.length} onClick={()=>{setPlaying(false);setComparisonA(captureComparison())}}>Capture A</button><button disabled={!carrier||!rivalPositions.length} onClick={()=>{setPlaying(false);setComparisonB(captureComparison())}}>Capture B</button><button onClick={()=>{setComparisonA(null);setComparisonB(null)}}>Clear comparison</button></div>{(comparisonA||comparisonB)&&<div style={{overflowX:'auto'}}><table style={{width:'100%',marginTop:12}}><thead><tr><th>Metric</th><th>Tactic A</th><th>Tactic B</th></tr></thead><tbody>{([{label:'Time (s)',key:'time'},{label:'Defense',key:'defense'},{label:'Press (%)',key:'press'},{label:'Compactness (%)',key:'compact'},{label:'Line height (%)',key:'line'},{label:'Open passes',key:'open'},{label:'Blocked passes',key:'blocked'},{label:'Space candidates',key:'spaces'},{label:'Team width',key:'width'},{label:'Team length',key:'length'},{label:'Opponent width',key:'opponentWidth'},{label:'Local superiority',key:'local'},{label:'Best pass score',key:'score'}] as {label:string;key:keyof TacticalSnapshot}[]).map(row=><tr key={row.key}><td>{row.label}</td>{[comparisonA,comparisonB].map((v,i)=><td key={i}>{typeof v?.[row.key]==='number'?Number(v[row.key]).toFixed(1):v?.[row.key]??'—'}</td>)}</tr>)}</tbody></table>{comparisonA&&comparisonB&&Math.abs(comparisonA.time-comparisonB.time)>.05&&<p style={{color:'#facc15'}}>Uyarı: farklı zaman noktaları karşılaştırılıyor.</p>}{comparisonA&&comparisonB&&<p>Açık pas farkı (B − A): {comparisonB.open-comparisonA.open} · Kapalı pas farkı: {comparisonB.blocked-comparisonA.blocked}. Bu değerler taktik başarı tahmini değildir.</p>}</div>}</section>}{duration>0&&<section aria-label="Tactical Timeline" style={{margin:'16px 0',padding:12,border:'1px solid #334155',borderRadius:8}}><h4>Tactical Timeline</h4><p>Bir hareket bloğuna tıklayarak başlangıcına gidin. {onMovements&&'Bloğu sürükleyerek beklemeyi, sağ kenarını sürükleyerek süreyi değiştirin.'}</p>{dragPreview!==null&&<p role="status">Yeni değer: {dragPreview} sn</p>}<div style={{overflowX:'auto'}}><div style={{minWidth:560}}><div style={{display:'flex',marginLeft:100,justifyContent:'space-between',fontSize:12}}>{Array.from({length:6},(_,i)=><span key={i}>{(duration*i/5).toFixed(1)}s</span>)}</div>{[...players.map((p,i)=>({p,i,rival:false})),...rivals.map((p,i)=>({p,i,rival:true}))].map(({p,i,rival})=>{const entries=timelines.flat().filter(v=>v.m.player===i&&!!v.m.rival===rival);if(!entries.length)return null;return <div key={(rival?'R':'P')+i} style={{display:'flex',alignItems:'center',marginTop:5}}><span style={{width:100,flexShrink:0,fontSize:12,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap',color:rival?'#fb7185':undefined}}>{rival?'R':'#'}{i+1} {p.name}</span><div data-timeline-track style={{position:'relative',height:32,flex:1,background:'#1e293b',borderRadius:4}}>{entries.map((v,j)=><button key={j} type="button" title={v.m.kind+' '+v.start+'–'+v.end+' sn'} aria-label={'Oyuncu '+(i+1)+' hareket '+(j+1)+' '+v.m.kind} onPointerDown={e=>beginEdit(e,v.m,'delay')} onPointerMove={moveEdit} onPointerUp={endEdit} onPointerCancel={cancelEdit} onClick={()=>{if(suppressClick.current){suppressClick.current=false;return}setPlaying(false);setTime(v.start)}} style={{touchAction:onMovements?'none':'auto',cursor:onMovements?'grab':'pointer',position:'absolute',left:(v.start/duration*100)+'%',width:((v.end-v.start)/duration*100)+'%',height:28,top:2,padding:0,overflow:'hidden',whiteSpace:'nowrap',fontSize:11,background:rival?'#fb7185':movementColors[v.m.kind],color:'#101827',border:'1px solid #101827',borderRadius:3}}>{v.m.kind} {j+1}</button>)}{onMovements&&entries.map((v,j)=><span key={'resize-'+j} aria-hidden="true" onPointerDown={e=>beginEdit(e,v.m,'duration')} onPointerMove={moveEdit} onPointerUp={endEdit} onPointerCancel={cancelEdit} style={{position:'absolute',left:(v.end/duration*100)+'%',transform:'translateX(-100%)',top:2,height:28,width:Math.min(8,Math.max(2,(v.end-v.start)/duration*460)),background:'#ffffff66',cursor:'ew-resize',touchAction:'none'}}/>)}<span aria-hidden="true" style={{position:'absolute',left:(t/duration*100)+'%',top:0,bottom:0,width:2,background:'white',pointerEvents:'none'}}/></div></div>})}</div></div></section>}<label>Zaman {t.toFixed(1)} / {duration} sn <input type="range" min="0" max={duration||1} step=".05" disabled={!duration} value={t} onChange={e=>{setPlaying(false);setTime(Number(e.target.value))}}/></label><p>{movements.length?timelines.flat().filter(v=>t>=v.start&&t<v.end).length+' aktif hareket · '+movements.length+' toplam hareket':'Önce taktik tahtasına hareket ekleyin.'}</p></section>
