const scenarioNames=['Hücum','Savunma','Geçiş','Korner','Serbest vuruş'] as const;
type BriefingSnapshot={version:1;approvedAt:string;scenarios:CoachSnapshot[]};
function printBriefing(snapshot:BriefingSnapshot,stale:boolean,selection?:{scenario:string;phase:Phase;slot:number}){
 const win=window.open('','_blank');
 if(!win)throw Error('Yazdırma penceresi engellendi.');
 try{
 win.opener=null;
 const d=win.document;d.title='Tactiqra — Player Briefing';
 const style=d.createElement('style');style.textContent='body{font:14px system-ui,sans-serif;color:#111;background:#fff;margin:24px}h1{font-size:24px}h2{font-size:19px}h3{font-size:15px}p{white-space:pre-wrap;overflow-wrap:anywhere}section{break-before:page}section:first-of-type{break-before:auto}article{break-inside:avoid}svg{width:100%;max-width:420px;display:block} @media print{button{display:none}body{margin:0}} @page{margin:15mm}';d.head.append(style);
 const add=(parent:HTMLElement,tag:string,value:string)=>{const e=d.createElement(tag);e.textContent=value;parent.append(e);return e};
 add(d.body,'h1',selection?'Tactiqra — Oyuncu görev kartı':'Tactiqra — Takım maç planı');
 add(d.body,'p','Onay: '+new Date(snapshot.approvedAt).toLocaleString()+(stale?' | Önceki onaylı sürüm':''));
 const button=d.createElement('button');button.textContent='Yazdır / PDF olarak kaydet';button.onclick=()=>win.print();d.body.append(button);
 for(const p of snapshot.scenarios){if(selection&&selection.scenario!==p.scenario)continue;for(const n of phaseNames){if(selection&&selection.phase!==n)continue;
 const active=p.phases[n],section=d.createElement('section');d.body.append(section);
 add(section,'h2',p.scenario+' · '+n+' · '+active.formation);add(section,'p','Rakip: '+p.opponent+' | Hedef: '+(p.objective||'Belirtilmedi'));
 const ns='http://www.w3.org/2000/svg',svg=d.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 120 80');svg.setAttribute('role','img');svg.setAttribute('aria-label','Başlangıç yerleşimi');
 const shape=(tag:string,attrs:Record<string,string|number>)=>{const e=d.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));svg.append(e);return e};
 shape('rect',{x:2,y:2,width:116,height:76,fill:'white',stroke:'black','stroke-width':.5});shape('path',{d:'M60 2V78M2 18H18V62H2M118 18H102V62H118',fill:'none',stroke:'black','stroke-width':.5});shape('circle',{cx:60,cy:40,r:9,fill:'none',stroke:'black','stroke-width':.5});
 active.board.forEach((x,i)=>{const focus=selection?.slot===i;shape('circle',{cx:x.x,cy:x.y,r:3,fill:focus?'black':'white',stroke:'black','stroke-width':.6});const label=shape('text',{x:x.x,y:x.y+1,'font-size':2.8,'text-anchor':'middle',fill:focus?'white':'black'});label.textContent=String(i+1)});section.append(svg);
 active.board.forEach((x,i)=>{if(selection&&selection.slot!==i)return;const article=d.createElement('article');section.append(article);add(article,'h3',(i+1)+'. '+(x.name||'Oyuncu '+(i+1)));add(article,'p',x.task||'Talimat henüz tanımlanmadı');active.movements.forEach((m,j)=>{if(m.player===i)add(article,'p','Adım '+(j+1)+' · '+m.kind+' → '+m.x.toFixed(1)+', '+m.y.toFixed(1))})});
 }}
 }catch(e){win.close();throw e}
}
function PlayerBriefing({plans}:{plans:CoachSnapshot[]}){
 const [approved,setApproved]=useState<BriefingSnapshot|null>(null);
 const [error,setError]=useState('');
 const [selected,setSelected]=useState<string>('Hücum');
 const [phase,setPhase]=useState<Phase>('In Possession');
 const [confirmed,setConfirmed]=useState(false);
 const [playerSlot,setPlayerSlot]=useState<number|null>(null);
 useEffect(()=>setPlayerSlot(null),[selected,phase,approved]);
 const presentationRef=React.useRef<HTMLDivElement>(null);
 const [fullError,setFullError]=useState('');
 const [printError,setPrintError]=useState('');
 const print=(individual:boolean)=>{if(!approved||stale||(individual&&(playerSlot===null||!Number.isInteger(playerSlot)||playerSlot<0||playerSlot>10)))return;try{printBriefing(approved,stale,individual&&playerSlot!==null?{scenario:selected,phase,slot:playerSlot}:undefined);setPrintError('')}catch{setPrintError('Yazdırma penceresi açılamadı. Tarayıcı izinlerini kontrol edin.')}};
 const fullscreen=async()=>{try{if(document.fullscreenElement===presentationRef.current){await document.exitFullscreen();return}if(!presentationRef.current?.requestFullscreen)throw Error('Tam ekran desteklenmiyor.');await presentationRef.current.requestFullscreen();setFullError('')}catch{setFullError('Tam ekran açılamadı; normal sunum kullanılabilir.')}};
 const step=(delta:number)=>{const index=scenarioNames.findIndex(n=>n===selected)*phaseNames.length+phaseNames.indexOf(phase);const next=Math.max(0,Math.min(scenarioNames.length*phaseNames.length-1,index+delta));setSelected(scenarioNames[Math.floor(next/phaseNames.length)]);setPhase(phaseNames[next%phaseNames.length])};
 const signature=JSON.stringify(plans);
 const stale=isBriefingStale(approved,plans);
 useEffect(()=>{setConfirmed(false)},[signature]);
 const approve=()=>{try{
  setApproved(approveBriefing(plans,confirmed,new Date().toISOString()));setConfirmed(false);setError('');
 }catch(e){setError(e instanceof Error?e.message:'Plan onaylanamadı.')}};
 const p=approved?.scenarios.find(x=>x.scenario===selected);
 const active=p?.phases[phase];
 return <section className="panel"><h3>Player Briefing</h3><p>Oyunculara gösterilecek onaylı plan kopyası. Analist kanıtları ve özel antrenör notları sunumda gösterilmez.</p><p>{plans.reduce((a,p)=>a+phaseNames.reduce((b,n)=>b+p.phases[n].board.filter(x=>x.task.trim()).length,0),0)}/165 oyuncu talimatı tanımlı. Eksik görevler sunumda belirtilir.</p><label><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Senaryoları, oyuncu isimlerini ve görevleri inceledim.</label><button type="button" disabled={!confirmed||plans.length!==scenarioNames.length} onClick={approve}>{approved?'Yeni sürümü onayla':'Sunum kopyasını onayla'}</button>{error&&<p role="alert">{error}</p>}{approved&&<><p>Onay zamanı: {new Date(approved.approvedAt).toLocaleString()}</p>{stale&&<p role="alert">Taslak değişti. Gösterilen sunum önceki onaylı sürümdür. Yazdırmak için yeni sürümü onaylayın.</p>}<label>Senaryo <select value={selected} onChange={e=>setSelected(e.target.value)}>{scenarioNames.map(n=><option key={n}>{n}</option>)}</select></label><label>Oyun evresi <select value={phase} onChange={e=>setPhase(e.target.value as Phase)}>{phaseNames.map(n=><option key={n}>{n}</option>)}</select></label>{p&&active&&<div ref={presentationRef} style={{background:'#101827',color:'#f1f5f9',padding:16,overflow:'auto'}}><div style={{display:'flex',flexWrap:'wrap',gap:8}}><button type="button" onClick={fullscreen}>Tam ekran / çık</button><button type="button" onClick={()=>step(-1)} disabled={selected===scenarioNames[0]&&phase===phaseNames[0]}>Önceki</button><button type="button" onClick={()=>step(1)} disabled={selected===scenarioNames[scenarioNames.length-1]&&phase===phaseNames[phaseNames.length-1]}>Sonraki</button></div>{fullError&&<p role="alert">{fullError}</p>}<p>{selected} · {phase} · {scenarioNames.findIndex(n=>n===selected)*3+phaseNames.indexOf(phase)+1}/15</p>{stale&&<p role="alert">Önceki onaylı sürüm</p>}<h4>{p.opponent} · {active.formation}</h4><p>{p.objective||'Hedef belirtilmedi'}</p><svg viewBox="0 0 120 80" role="img" aria-label={selected+' '+phase+' taktik yerleşimi'} style={{width:'100%',maxHeight:'65vh',display:'block'}}><rect width="120" height="80" fill="#174535"/><g fill="none" stroke="#b5d4bd" strokeWidth=".45"><rect x="2" y="2" width="116" height="76"/><path d="M60 2V78M2 18H18V62H2M118 18H102V62H118M2 30H8V50H2M118 30H112V50H118"/><circle cx="60" cy="40" r="9"/></g>{active.zones.map((z,i)=><g key={i}><rect x={z.x} y={z.y} width={z.w} height={z.h} fill="#fbbf24" fillOpacity=".18" stroke="#fbbf24" strokeWidth=".4"/><text x={z.x+z.w/2} y={z.y+3} fontSize="2.5" textAnchor="middle" fill="white">{z.kind}</text></g>)}{active.showRivals&&active.rivals.map((x,i)=><circle key={i} cx={x.x} cy={x.y} r="2.7" fill="#ef4444" stroke="white" strokeWidth=".3"/>)}{active.board.map((x,i)=><g key={i}><circle cx={x.x} cy={x.y} r="3" fill={playerSlot===i?"#fbbf24":"#60a5fa"} stroke="white" strokeWidth=".4"/><text x={x.x} y={x.y+1} textAnchor="middle" fontSize="2.8" fill="#101827" fontWeight="bold">{i+1}</text></g>)}</svg><TacticalPlayback key={approved.approvedAt+'-'+selected+'-'+phase} initialOwnerChoice={active.initialOwnerChoice??-1} players={active.board} movements={active.movements} rivals={active.showRivals?active.rivals:[]} highlight={playerSlot}/><h4>Printable Briefing</h4><button type="button" disabled={stale} onClick={()=>print(false)}>Takım planını yazdır</button><button type="button" disabled={stale||playerSlot===null} onClick={()=>print(true)}>Seçili oyuncu kartını yazdır</button>{printError&&<p role="alert">{printError}</p>}<h4>Individual Player Cards</h4><label>Oyuncu <select value={playerSlot===null?'all':String(playerSlot)} onChange={e=>setPlayerSlot(e.target.value==='all'?null:Number(e.target.value))}><option value="all">Tüm takım</option>{active.board.map((x,i)=><option key={i} value={i}>{i+1}. {x.name||'Oyuncu '+(i+1)}</option>)}</select></label>{playerSlot!==null&&active.board[playerSlot]&&<section aria-label="Oyuncu görev kartı"><h4>{active.board[playerSlot].name||'Oyuncu '+(playerSlot+1)} · {active.formation}</h4><p>{selected} · {phase}</p><p>Başlangıç konumu: {active.board[playerSlot].x.toFixed(1)}, {active.board[playerSlot].y.toFixed(1)}</p><p style={{whiteSpace:'pre-wrap'}}>{active.board[playerSlot].task||'Talimat henüz tanımlanmadı'}</p><h5>Atanan hareketler (plan sırası)</h5>{active.movements.filter(m=>m.player===playerSlot).length===0?<p>Hareket tanımlanmadı.</p>:<ol>{active.movements.map((m,i)=>({m,i})).filter(({m})=>m.player===playerSlot).map(({m,i})=><li key={i}>{i+1}. {m.kind==='Run'?'Koşu':m.kind==='Pass'?'Pas':'Pres'} → ({m.x.toFixed(1)}, {m.y.toFixed(1)})</li>)}</ol>}<p>Oyuncu seçimi bu evredeki tahta sırasına bağlıdır; başka evreye geçince yeniden seçin.</p></section>}{playerSlot===null&&active.board.map((x,i)=><p key={i}><strong>{i+1}. {x.name||'Oyuncu '+(i+1)}</strong> — {x.task||'Talimat henüz tanımlanmadı'}</p>)}</div>}</>}</section>
}
function CoachWorkspace({evidence}:{evidence:string[]}){
 const targets=React.useContext(WorkspaceContext);
 const [scenario,setScenario]=useState<typeof scenarioNames[number]>('Hücum');
 const [plans,setPlans]=useState<Record<string,CoachSnapshot>>({});
 const receive=React.useCallback((p:CoachSnapshot)=>setPlans(old=>({...old,[p.scenario]:p})),[]);
 const ordered=scenarioNames.flatMap(n=>plans[n]?[plans[n]]:[]);
 const [exportError,setExportError]=useState('');
 const download=()=>{try{for(const p of ordered)validateCoachPlan(p,p.scenario);const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,kind:'complete-match-plan',scenarios:ordered,evidence},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='tactiqra-complete-match-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setExportError('')}catch{setExportError('Plan doğrulanamadı; görevleri ve koordinatları kontrol edin.')}};
 return <section>{[targets.training,targets.player,targets.team].map((target,i)=>target&&createPortal(<div className="filters" style={{marginBottom:12}}><label>Plan scenario <select value={scenario} onChange={e=>setScenario(e.target.value as typeof scenario)}>{scenarioNames.map(n=><option key={n}>{n}</option>)}</select></label><button type="button" onClick={()=>targets.open('CoachIQ')}>Open CoachIQ</button></div>,target,'scenario-nav-'+i))}<section className="panel"><h3>Complete Match Plan</h3><p>Canlı taslak özeti · {ordered.length}/5 senaryo · Antrenör onayı bekliyor.</p>{ordered.map(p=><details key={p.scenario}><summary>{p.scenario} · {p.opponent||'Rakip belirtilmedi'}</summary><p>Hedef: {p.objective||'Belirtilmedi'}</p>{phaseNames.map(n=><p key={n}>{n} · {p.phases[n].formation} · {p.phases[n].board.filter(x=>x.task.trim()).length}/11 talimat · {p.phases[n].movements.length} hareket</p>)}<p>Görevler: {p.tasks.filter(x=>x.done).length}/{p.tasks.length}</p></details>)}{new Set(ordered.map(p=>p.opponent.trim().toLowerCase()).filter(Boolean)).size>1&&<p role="alert">Senaryolarda farklı rakip isimleri var; dışa aktarmadan önce doğrulayın.</p>}<button type="button" disabled={ordered.length!==scenarioNames.length} onClick={download}>Tüm maç planını indir (JSON)</button>{exportError&&<p role="alert">{exportError}</p>}</section><PlayerBriefing plans={ordered}/><nav className="tabs" aria-label="Taktik senaryoları" style={{display:'flex',flexWrap:'wrap',gap:8,marginBottom:16}}>{scenarioNames.map(n=><button type="button" key={n} className={scenario===n?'active':''} aria-pressed={scenario===n} onClick={()=>setScenario(n)}>{n}</button>)}</nav>{scenarioNames.map(n=><div key={n} hidden={scenario!==n}><CoachPlan evidence={evidence} scenario={n} onSnapshot={receive} active={scenario===n}/></div>)}</section>
}
const phaseNames=['In Possession','Out of Possession','Transition'] as const;
type Phase=typeof phaseNames[number];
function initialPhase(){return {initialOwnerChoice:-1,formation:'4-3-3' as Formation,board:formationPlayers('4-3-3'),movements:[] as Movement[],zones:[] as Zone[],showRivals:false,rivals:formationPlayers('4-3-3').map(p=>({...p,x:120-p.x}))}}
function tacticalReview(e:string){
 const score=e.match(/ · (\d+)\/(\d+) maç · .*? · G\/B\/M \d+\/\d+\/\d+ · Gol (\d+)\/(\d+) · Maç ID: /);
 const shots=e.match(/ · Şutlar: (\d+) \/ (\d+) · /);
 const box=e.match(/ · Ceza sahası şutları \(ham koordinatlar\): (\d+) \/ (\d+) · /);
 const xg=e.match(/ · Kaynak xG: (\d+(?:\.\d+)?) \/ (\d+(?:\.\d+)?) · /);
 const items:{finding:string;action:string}[]=[];
 if(score&&e.includes(' · football-data.org · ')&&Number(score[1])>0){items.push({finding:score[1]+'/'+score[2]+' maç; atılan/yenilen gol '+score[3]+'/'+score[4],action:'Gol pozisyonlarını video ve olay verisiyle incele; skorlar üzerinden pres veya diziliş çıkarma.'});if(Number(score[1])<Number(score[2]))items.push({finding:'İstenen maç kapsamı tamamlanmadı.',action:'Eksik maçları doğrula; genelleme yapmadan önce kapsamı genişlet.'})}
 if(shots&&e.includes(' | Match #'))items.push({finding:'Ev/deplasman şutları: '+shots[1]+'/'+shots[2],action:'Şut haritasında iki takımın şut konumlarını incele; savunma ve hücum antrenmanı önceliğini video ile doğrula.'});
 if(box&&shots&&Number(box[1])<=Number(shots[1])&&Number(box[2])<=Number(shots[2]))items.push({finding:'Ham koordinatlarla ceza sahası şutları: '+box[1]+'/'+box[2],action:'Ceza sahasına giriş ve alan savunması kliplerini incele; koordinat yönünü doğrula.'});
 if(xg&&shots)items.push({finding:'Kaynak xG (ev/deplasman): '+xg[1]+'/'+xg[2],action:'Şut kalitesi ve bitiricilik farkını incele; tek maçtan kalıcı zayıflık çıkarma.'});
 return items;
}
type CoachSnapshot={version:number;scenario:string;opponent:string;objective:string;notes:string;tasks:{id:number;label:string;done:boolean}[];phase:Phase;phases:Record<Phase,ReturnType<typeof initialPhase>>};
