 const save=(next:TrainingDrill[])=>{setDrills(next);try{localStorage.setItem(key,JSON.stringify(next.map(d=>({...d,plan:null}))));setStatus('Egzersiz bilgileri yerel olarak kaydedildi; animasyon bağlantısı yalnızca bu oturumda saklanır.')}catch{setStatus('Yerel kayıt başarısız; mevcut oturumda kullanılabilir.')}};
 const add=()=>{if(!name.trim()||drills.length>=100)return;save([...drills,{id:crypto.randomUUID(),day,name:name.trim(),goal:goal.trim(),players:count,width,length,minutes,reps,rest,phase,plan:link?JSON.parse(JSON.stringify(source==='coach'?phases[phase]:trainingPlan)):null}]);setName('');setGoal('');setView('Weekly Planner')};
 const print=()=>{const w=window.open('','_blank');if(!w){setStatus('Yazdırma penceresi engellendi.');return}w.opener=null;const d=w.document;d.title='Tactiqra Training Plan';const css=d.createElement('style');css.textContent='@page{size:A4;margin:15mm}body{font:13px system-ui;color:#18252b}section{break-inside:avoid;border-bottom:1px solid #ccc;padding:8px 0}p{white-space:pre-wrap;overflow-wrap:anywhere}@media print{button{display:none}}';d.head.append(css);const el=(tag:string,value:string,parent:HTMLElement=d.body)=>{const e=d.createElement(tag);e.textContent=value;parent.append(e);return e};el('button','Print / Save PDF').onclick=()=>w.print();el('h1','TACTIQRA / Weekly Training Plan');el('p',scenario+' · Total: '+drills.reduce((a,b)=>a+total(b),0)+' min');days.forEach(day=>{const list=drills.filter(v=>v.day===day);if(!list.length)return;el('h2',day+' · '+list.reduce((a,b)=>a+total(b),0)+' min');list.forEach(v=>{const sec=d.createElement('section');d.body.append(sec);el('h3',v.name,sec);el('p',v.goal||'—',sec);el('p',v.players+' players · '+v.width+' × '+v.length+' m · '+v.reps+' × '+v.minutes+' min · Rest '+v.rest+' min · Total '+total(v)+' min · '+v.phase,sec)})});w.focus()};
 const numeric=[{label:'Players',value:count,set:setCount,min:1,max:30},{label:'Width (m)',value:width,set:setWidth,min:5,max:100},{label:'Length (m)',value:length,set:setLength,min:5,max:120},{label:'Minutes / rep',value:minutes,set:setMinutes,min:1,max:120},{label:'Reps',value:reps,set:setReps,min:1,max:20},{label:'Rest (min)',value:rest,set:setRest,min:0,max:30}];
 const active=drills.find(d=>d.id===preview);
 return <section style={{marginTop:24,border:'1px solid #34464a',borderRadius:8,padding:14}}><h3>TrainingIQ · {view}</h3><nav className="tabs" style={{display:'flex',flexWrap:'wrap',gap:8}}>{['Overview','Weekly Planner','Session Builder','Exercise Library','Training Board','Training Reports'].map(v=><button type="button" key={v} className={view===v?'active':''} onClick={()=>setView(v)}>{v}</button>)}</nav>{view==='Overview'&&<><div className="metrics"><div className="metric"><span>Exercises</span><strong>{drills.length}</strong></div><div className="metric"><span>Weekly minutes</span><strong>{drills.reduce((a,b)=>a+total(b),0)}</strong></div><div className="metric"><span>Training days</span><strong>{new Set(drills.map(d=>d.day)).size}</strong></div></div><button type="button" onClick={()=>setView('Exercise Library')}>Browse exercises</button> <button type="button" onClick={()=>setView('Session Builder')}>Create exercise</button></>}{view==='Exercise Library'&&<><p>Editable coaching templates; suggested workloads are examples, not individualized prescriptions.</p><label>Category <select value={category} onChange={e=>setCategory(e.target.value)}>{['All','Possession','Defending','Transition','Attacking'].map(c=><option key={c}>{c}</option>)}</select></label><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(220px,1fr))',gap:12}}>{templates.filter(v=>category==='All'||v.category===category).map(v=><article key={v.name} style={{border:'1px solid #34464a',padding:12,borderRadius:8}}><small>{v.category}</small><h4>{v.name}</h4><p>{v.goal}</p><p>{v.players} players · {v.width} × {v.length} m · {v.reps} × {v.minutes} min</p><button type="button" onClick={()=>loadTemplate(v)}>Use exercise</button></article>)}</div></>}{view==='Training Board'&&<><DrillDesigner scenario={scenario}/><h4>Animated Tactical Board</h4><p>Independent practice board. Full 11-player tactical layout; exercise dimensions and player count are planning metadata.</p><button type="button" onClick={()=>{if(window.confirm('Replace training board with current CoachIQ phase?'))setTrainingPlan(JSON.parse(JSON.stringify(phases[phase])))}}>Copy CoachIQ phase</button> <button type="button" onClick={()=>{if(window.confirm('Reset training board?'))setTrainingPlan(initialPhase())}}>Reset board</button><TacticalBoard initialOwnerChoice={trainingPlan.initialOwnerChoice??-1} onInitialOwner={n=>setTrainingPlan(p=>({...p,initialOwnerChoice:n}))} formation={trainingPlan.formation} players={trainingPlan.board} onPlayers={v=>patchTraining({board:v})} onFormation={f=>patchTraining({formation:f,board:formationPlayers(f),movements:[]})} movements={trainingPlan.movements} onMovements={v=>patchTraining({movements:v})} zones={trainingPlan.zones} onZones={v=>patchTraining({zones:v})} rivals={trainingPlan.rivals} onRivals={v=>patchTraining({rivals:v})} showRivals={trainingPlan.showRivals} onShowRivals={v=>patchTraining({showRivals:v})}/><TacticalPlayback initialOwnerChoice={trainingPlan.initialOwnerChoice??-1} onInitialOwner={n=>setTrainingPlan(p=>({...p,initialOwnerChoice:n}))} players={trainingPlan.board} movements={trainingPlan.movements} rivals={trainingPlan.showRivals?trainingPlan.rivals:[]} onMovements={v=>patchTraining({movements:v})}/><button type="button" onClick={()=>{setSource('training');setLink(true);setView('Session Builder')}}>Use board in exercise</button></>}{view==='Session Builder'&&<><p>Haftalık şablon; takvim tarihleri içermez.</p><div className="filters"><label>Day <select value={day} onChange={e=>setDay(e.target.value)}>{days.map(d=><option key={d}>{d}</option>)}</select></label><label>Exercise <input value={name} maxLength={100} onChange={e=>setName(e.target.value)} placeholder="High press drill"/></label><label>Objective <input value={goal} maxLength={500} onChange={e=>setGoal(e.target.value)}/></label>{numeric.map(n=><label key={n.label}>{n.label}<input type="number" min={n.min} max={n.max} value={n.value} onChange={e=>n.set(Math.max(n.min,Math.min(n.max,Math.round(Number(e.target.value)||0))))}/></label>)}</div><label><input type="checkbox" checked={link} onChange={e=>setLink(e.target.checked)}/> Attach tactical animation</label><label>Animation source <select value={source} onChange={e=>setSource(e.target.value as typeof source)}><option value="coach">CoachIQ · {phase}</option><option value="training">Training Board</option></select></label><div className="filters"><button type="button" disabled={!name.trim()||drills.length>=100} onClick={add}>Add exercise</button><span>Weekly total: {drills.reduce((a,b)=>a+total(b),0)} min</span></div></>}{view==='Training Reports'&&<><p>Weekly total: {drills.reduce((a,b)=>a+total(b),0)} min</p><button type="button" disabled={!drills.length} onClick={print}>Print weekly plan / PDF</button></>}<p role="status">{status}</p>{(view==='Weekly Planner'||view==='Training Reports')&&<>{days.map(d=>{const list=drills.filter(v=>v.day===d);return <details key={d} open={d===day||undefined}><summary>{d} · {list.length} exercises · {list.reduce((a,b)=>a+total(b),0)} min</summary>{list.map(v=><div key={v.id} style={{padding:10,borderBottom:'1px solid #34464a'}}><strong>{v.name}</strong><p>{v.goal} · {v.players} players · {v.width} × {v.length} m · {v.reps} × {v.minutes} min · Rest {v.rest} min · {total(v)} min</p><button type="button" disabled={!v.plan} onClick={()=>setPreview(preview===v.id?null:v.id)}> {preview===v.id?'Hide animation':'Preview animation'}</button> <button type="button" onClick={()=>{if(window.confirm('Remove exercise?'))save(drills.filter(x=>x.id!==v.id))}}>Delete</button></div>)}</details>})}{active?.plan&&<TacticalPlayback key={active.id} initialOwnerChoice={active.plan.initialOwnerChoice??-1} players={active.plan.board} movements={active.plan.movements} rivals={active.plan.showRivals?active.plan.rivals:[]}/>}</>}</section>
